// for await over untyped values in JavaScript: a recursive async generator
// (its return type is `any` to the checker, as in @vercel/build-utils'
// createFunctionsIterator), custom async iterables, synchronous iterables
// of promises, and yield* inside async generators.
'use strict';
var SUFFIX = '.func';
async function* walkTree(dir, root = dir, entries) {
  for (let name of entries[dir] || []) {
    let abs = dir + '/' + name;
    name.endsWith(SUFFIX) ? yield abs.slice(root.length + 1, abs.length - SUFFIX.length) : yield* walkTree(abs, root, entries);
  }
}

async function collect(dir, entries) {
  var out = [];
  for await (let path of walkTree(dir, dir, entries)) out.push(path);
  return out;
}

function countdown(n, log) {
  return {
    [Symbol.asyncIterator]() {
      var left = n;
      return {
        next() {
          log.push('next');
          return Promise.resolve(left > 0 ? { value: left--, done: false } : { value: undefined, done: true });
        },
        return() {
          log.push('return');
          return Promise.resolve({ value: undefined, done: true });
        },
      };
    },
  };
}

function* syncValues() {
  yield Promise.resolve('g1');
  yield 'g2';
}

async function* delegating(items) {
  var tail = yield* inner();
  yield* items;
  yield 'tail:' + tail;
}

async function* inner() {
  yield 'inner-a';
  yield 'inner-b';
  return 'done';
}

async function protocols() {
  var out = [];
  var log = [];
  for await (var n of countdown(3, log)) out.push('n' + n);
  out.push(log.join(','));
  log.length = 0;
  for await (var m of countdown(5, log)) {
    if (m === 4) break;
    out.push('m' + m);
  }
  out.push(log.join(','));
  log.length = 0;
  try {
    for await (var k of countdown(2, log)) throw new Error('body ' + k);
  } catch (error) {
    out.push(error.message, log.join(','));
  }
  for await (var p of [Promise.resolve('p1'), Promise.resolve('p2')]) out.push(p);
  for await (var g of syncValues()) out.push(g);
  for await (var d of delegating(['x', Promise.resolve('y')])) out.push(d);
  var notIterable = 42;
  try {
    for await (var z of notIterable) out.push(z);
  } catch (error) {
    out.push(error.name + ': ' + error.message);
  }
  return out;
}

module.exports = { collect, protocols };
